const action = $('Webhook').item.json.body?.action;
const horsLot = ['correct', 'regenerate', 'validate', 'get_dossier'];
const message = horsLot.includes(action)
  ? `L'action « ${action} » n'est pas encore disponible dans cette version.`
  : `Action inconnue : « ${action ?? 'absente'} ».`;
return [{ json: { erreur: { code: 'action_indisponible', message } } }];

const categories = ['toiture', 'facade', 'volets', 'menuiseries', 'margelles', 'plage'];
const groupes = Object.fromEntries(categories.map((c) => [c, []]));
for (const item of $input.all()) {
  const ligne = item.json;
  if (groupes[ligne.categorie]) {
    groupes[ligne.categorie].push({ id: ligne.id, terme: ligne.terme });
  }
}
return [{ json: { materiaux: groupes } }];

const body = $json.body ?? {};
const erreurs = [];
if (!body.reference || typeof body.reference !== 'string' || body.reference.trim() === '') {
  erreurs.push('la référence du dossier est manquante');
}
if (!body.images || !body.images.cadrage) {
  erreurs.push('la vue de cadrage est manquante');
}
if (!body.style) {
  erreurs.push('le style de rendu est manquant');
}
return [{ json: { valide: erreurs.length === 0, erreurs } }];

const erreurs = $json.erreurs ?? [];
return [{
  json: {
    erreur: {
      code: 'requete_invalide',
      message: `La demande de génération est incomplète : ${erreurs.join(', ')}.`,
    },
  },
}];

const requete = $('Webhook').item.json.body;
const categories = ['toiture', 'facade', 'volets', 'menuiseries', 'margelles', 'plage'];
const ids = [];
for (const c of categories) {
  const selection = requete.materiaux ? requete.materiaux[c] : null;
  if (selection && selection.origine === 'catalogue' && selection.id) ids.push(selection.id);
}
return [{ json: { idsCatalogue: ids } }];

// ---------------------------------------------------------------------------
// BROUILLON À VALIDER — voir docs/n8n-setup.md « Contenu à compléter ».
// Ce contenu est un premier jet cohérent avec le PRD (§1.2, §1.3, §6) et les
// règles de rédaction de docs/fragments-prompt.md, PAS le texte calibré du
// workflow V1. Colle ici le texte réel si tu l'as déjà (pipeline inchangé
// selon le PRD), sinon calibre celui-ci sur un dossier réel avant mise en
// production, comme pour les fragments de ciel/pelouse/éclairages.
// ---------------------------------------------------------------------------

const SYSTEME = `Tu produis une image photoréaliste d'un projet architectural à partir des vues fournies. Contrainte impérative, prioritaire sur toute autre considération : la géométrie de la vue de cadrage fait autorité et ne doit jamais être modifiée — formes, volumes, proportions, niveaux, ouvertures, toiture, implantation, cadrage et perspective restent strictement identiques à la vue fournie. Un résultat esthétiquement réussi mais géométriquement inexact constitue un échec, quelle que soit par ailleurs la qualité visuelle obtenue. Le rendu attendu est réaliste : aucun style illustratif, pictural ou stylisé, quel que soit le style demandé par ailleurs. Le style agit uniquement sur la lumière et la présentation, jamais sur l'architecture. N'invente, n'ajoute, ne supprime et ne déplace aucune ouverture, aucun volume, aucun élément secondaire. Un matériau ou un élément dont la nature n'est pas identifiable n'est pas interprété : il est reproduit tel qu'il apparaît, sans supposition.`;

const MODE_PRODUCTION = {
  photomontage_controle: "Intègre le projet directement sur la photographie du site fournie, en respectant exactement son point de vue, sa perspective et sa lumière d'origine. Les zones de la vue de cadrage sans contenu défini sont complétées par le contenu réel visible sur la photographie du site, jamais par un décor inventé ; un ciel seul reste acceptable en l'absence de tout élément environnant visible.",
  presentation_generative: "Présente le projet dans un environnement cohérent inspiré de la photographie du site, sans chercher un alignement géométrique strict avec celle-ci : la photographie sert de référence de matières, de végétation et d'ambiance, pas de calque d'intégration.",
  retexturation_revit: "Aucune photographie du site n'est fournie. Complète les zones vides de la vue de cadrage par un environnement extérieur plausible et sobre, cohérent avec le projet, sans effet de composition ni décor remarquable.",
};

const STYLE = {
  photomontage_administratif: {
    intro: "Présentation sobre destinée à un usage administratif (permis de construire, dépôt réglementaire). Restitution fidèle et neutre, sans embellissement ni mise en scène.",
    suite: "Matières rendues avec précision et sans effet décoratif ; profondeur de champ nette sur l'ensemble du projet ; finition photographique neutre, sans grain artistique ni vignettage.",
  },
  presentation_client: {
    intro: "Présentation destinée à une réunion ou un avant-projet client. Restitution flatteuse mais crédible, qui met le projet en valeur sans s'éloigner du réalisme photographique.",
    suite: "Matières rendues avec un relief soigné ; légère profondeur de champ recentrée sur le projet ; finition photographique nette et engageante.",
  },
  commercial: {
    intro: "Présentation destinée à la communication institutionnelle ou commerciale. Restitution valorisante et soignée, tout en restant strictement photoréaliste.",
    suite: "Matières rendues avec un relief marqué et une belle profondeur de champ ; finition proche d'une photographie d'architecture professionnelle, nette et contrastée.",
  },
};

// Fragments ci-dessous copiés tels quels depuis docs/fragments-prompt.md — ne
// pas les reformuler ailleurs que dans ce fichier source.
const CIEL = {
  reprendre_photo: "La lumière, la direction du soleil, la douceur des ombres et la température de couleur sont reprises exactement de la photographie du site. Les ombres portées des éléments projetés tombent dans la même direction, avec la même longueur et la même densité que celles déjà visibles sur la photographie. Le ciel est celui de la photographie, avec sa texture nuageuse et sa profondeur atmosphérique propres. L'image entière doit paraître capturée en une seule prise de vue : même grain, même contraste, même dominante colorée du premier plan jusqu'à l'horizon.",
  degage: "Ciel bleu franc et dégagé, plus soutenu au zénith et s'éclaircissant progressivement vers l'horizon, avec une profondeur atmosphérique perceptible. Soleil haut, lumière directe : ombres portées nettes, aux bords légèrement adoucis à mesure qu'elles s'éloignent de l'objet qui les projette, densité soutenue conservant du détail dans les zones sombres. Les surfaces claires gardent leur texture et leur gradation tonale sur toute leur étendue. Température de couleur neutre de plein jour.",
  legerement_voile: "Ciel couvert d'un voile de nuages hauts et fins, laissant deviner la position du soleil sans disque nettement dessiné. Lumière directionnelle mais adoucie : les ombres portées restent lisibles, avec des bords diffus et une densité modérée. Contraste doux, gradation fine sur les surfaces courbes et sur le grain des enduits. Température de couleur neutre, très légèrement froide.",
  neutre_diffus: "Lumière naturelle neutre et diffuse de ciel uniformément couvert. Aucune direction dominante : les ombres sont courtes et très douces, essentiellement des ombres de contact au pied des volumes, sous les débords de toiture et dans les feuillures des ouvertures. Ciel clair et uniformément lumineux, conservant une légère texture nuageuse. Contraste faible mais tonalité pleine, chaque matériau restant lisible dans son relief et sa texture propre.",
  fin_de_journee: "Fin d'après-midi, soleil bas sur l'horizon. Lumière rasante et chaude, ambrée sans excès, qui révèle le relief des enduits, des tuiles et des pierres et allonge les ombres portées dans une direction unique et cohérente. Les façades exposées reçoivent une lumière dorée ; les façades opposées basculent dans une ombre légèrement bleutée, éclairée par la seule lumière du ciel. Ciel en dégradé, du bleu profond au zénith vers des tons chauds près de l'horizon, avec une texture nuageuse réelle. Contraste marqué, conservant du détail dans les hautes lumières comme dans les ombres.",
  crepuscule: "Crépuscule, peu après le coucher du soleil. Le ciel conserve une luminosité résiduelle et se dégrade du bleu profond au zénith vers des tons orangés puis violacés près de l'horizon, avec une texture nuageuse réelle. Plus aucune lumière solaire directe : l'éclairage extérieur provient uniquement de la voûte céleste, doux et enveloppant, et des sources artificielles allumées. Les façades prennent une tonalité bleutée froide qui contraste avec la chaleur des éclairages. Équilibre d'exposition d'une photographie d'architecture à l'heure bleue : le ciel reste lisible, les zones éclairées ne sont pas brûlées, les zones sombres conservent leur détail.",
};

const ECLAIRAGES = {
  margelles: "Éclairage linéaire encastré en périphérie du bassin, sous le nez des margelles : lumière chaude et rasante qui souligne le tracé de la piscine et révèle la texture de la pierre en lumière frisante. Intensité discrète, sans halo débordant ni source visible.",
  sous_marin: "Projecteurs immergés dans le bassin, lumière blanche légèrement froide diffusée dans la masse d'eau. L'eau devient translucide et lumineuse de l'intérieur, laissant voir le fond et les parois du bassin. Reflets ondulants portés sur les margelles et sur les surfaces claires les plus proches.",
  appliques_facade: "Appliques murales allumées en façade, lumière chaude dirigée vers le haut et vers le bas, dessinant des cônes lumineux doux sur l'enduit et révélant son grain en lumière rasante. Halos contenus, dégradé progressif jusqu'à l'ombre, sans surexposition autour des sources.",
  interieur_visible: "Éclairage intérieur allumé, visible à travers les baies et les fenêtres : lumière chaude, plus dense que l'ambiance extérieure, laissant deviner la profondeur des pièces sans en détailler le contenu. Les vitrages passent d'un aspect sombre et réfléchissant à une transparence lumineuse.",
};

const PELOUSE = {
  telle_quelle: "La pelouse et la végétation basse sont reprises fidèlement de la photographie du site : même hauteur d'herbe, même densité, mêmes nuances d'une zone à l'autre, y compris les irrégularités présentes.",
  tondue_soignee: "Pelouse récemment tondue et régulièrement entretenue. Les brins d'herbe sont individuellement visibles, dressés avec une orientation naturellement variée, de hauteur régulière, avec de petites ombres douces entre eux à courte distance. Vert sain et homogène, dont les variations de ton d'une zone à l'autre restent légères et contenues. Couverture continue et dense jusqu'aux bordures.",
  fleurie: "Pelouse d'agrément légèrement fleurie, dans le registre de la prairie entretenue. Les brins d'herbe restent individuellement visibles, de hauteur régulière, dans un vert sain dont les variations de ton restent contenues. Quelques marguerites et petites fleurs blanches et jaunes émergent au-dessus de l'herbe, dispersées en petits groupes irréguliers plutôt qu'en semis uniforme. L'ensemble reste manifestement entretenu.",
};

const LABELS_CATEGORIE = {
  toiture: 'toiture',
  facade: 'façade',
  volets: 'volets',
  menuiseries: 'menuiseries',
  margelles: 'margelles',
  plage: 'plage de piscine',
};

// ---------------------------------------------------------------------------
// Assemblage — logique tirée de docs/contrat-webhook-n8n.md et
// docs/fragments-prompt.md §2 (précédence ciel / bloc de style).
// ---------------------------------------------------------------------------

const requete = $('Webhook').item.json.body;
const fragmentsRows = $input.all().map((i) => i.json);
const fragmentsParId = Object.fromEntries(fragmentsRows.map((r) => [r.id, r.fragment_prompt]));

const sections = [];
sections.push(['SYSTÈME', SYSTEME]);
sections.push(['MODE DE PRODUCTION', MODE_PRODUCTION[requete.mode_production] ?? '']);

// Style + lumière : le fragment de ciel remplace toujours le paragraphe
// lumière du bloc de style (docs/fragments-prompt.md §2). Un seul bloc de
// style par appel, jamais deux blocs parlant de lumière.
const styleBloc = STYLE[requete.style];
if (styleBloc) {
  sections.push(['STYLE', [styleBloc.intro, styleBloc.suite].join(' ')]);
}
const cielFragment = CIEL[requete.environnement?.ciel];
if (cielFragment) {
  sections.push(['LUMIÈRE ET AMBIANCE', cielFragment]);
}

// Éclairages : uniquement si la question a été posée (objet non nul).
const eclairages = requete.environnement?.eclairages;
if (eclairages) {
  const allumes = Object.entries(eclairages)
    .filter(([, actif]) => actif === true)
    .map(([cle]) => ECLAIRAGES[cle])
    .filter(Boolean);
  if (allumes.length > 0) {
    sections.push(['ÉCLAIRAGES ALLUMÉS', allumes.join(' ')]);
  }
}

// Matériaux — jamais de matériau_libre ici, uniquement catalogue/existant.
const categories = ['toiture', 'facade', 'volets', 'menuiseries', 'margelles', 'plage'];
const materiauxTexte = [];
for (const c of categories) {
  const selection = requete.materiaux ? requete.materiaux[c] : null;
  if (!selection) continue;
  const label = LABELS_CATEGORIE[c];
  if (selection.origine === 'catalogue') {
    const fragment = fragmentsParId[selection.id];
    if (fragment) {
      materiauxTexte.push(`${label} : ${fragment}.`);
    } else {
      // Aucune invention (PRD §6.1) : on signale plutôt que d'improviser.
      materiauxTexte.push(`${label} : matériau non calibré (« ${selection.terme} »), aucune instruction de matière fournie — ne pas interpréter.`);
    }
  } else if (selection.origine === 'existant') {
    materiauxTexte.push(`${label} : reprends exactement l'aspect visible sur la photographie du site pour cet élément, sans réinterprétation ni remplacement.`);
  }
}
if (materiauxTexte.length > 0) {
  sections.push(['MATÉRIAUX', materiauxTexte.join(' ')]);
}

// Environnement.
const environnementTexte = [];
if (requete.environnement?.conserver_vegetation) {
  environnementTexte.push("La végétation existante visible sur la photographie du site est conservée : mêmes essences, même implantation, même volume, avec une variation de couleur bornée et sans aspect irrégulier.");
}
const pelouseFragment = PELOUSE[requete.environnement?.aspect_pelouse];
if (pelouseFragment) environnementTexte.push(pelouseFragment);
const elementsARetirer = (requete.environnement?.elements_a_retirer ?? '').trim();
if (elementsARetirer) {
  environnementTexte.push(`Retire de l'image les éléments suivants, sans modifier ni recomposer le reste de la scène : ${elementsARetirer}.`);
}
if (environnementTexte.length > 0) {
  sections.push(['ENVIRONNEMENT', environnementTexte.join(' ')]);
}

const elementsAPreserver = (requete.elements_a_preserver ?? '').trim();
if (elementsAPreserver) {
  sections.push(['ÉLÉMENTS À PRÉSERVER', `Conserve strictement les éléments suivants tels qu'ils apparaissent sur les vues fournies, sans les réinterpréter : ${elementsAPreserver}.`]);
}

const precisions = (requete.precisions ?? '').trim();
if (precisions) {
  sections.push(['PRÉCISIONS', precisions]);
}

const promptComplet = sections.map(([titre, texte]) => `[${titre}]
${texte}`).join('\n\n');

const imageUrls = [requete.images.cadrage];
if (requete.images.site) imageUrls.push(requete.images.site);

const payloadFal = {
  prompt: promptComplet,
  image_urls: imageUrls,
  aspect_ratio: '4:3',
  resolution: '2K',
  seed: 42,
};

return [{
  json: {
    reference: requete.reference,
    promptComplet,
    payloadFal,
  },
}];

const statut = $input.first().json;
const precedent = $('Attendre').item.json;
return [{
  json: {
    status: statut.status,
    status_url: precedent.status_url,
    response_url: precedent.response_url,
    tentative: (precedent.tentative ?? 0) + 1,
  },
}];

return [{
  json: {
    erreur: {
      code: 'delai_depasse',
      message: "La génération prend trop de temps. Réessaie dans quelques minutes ; si le problème persiste, contacte le support.",
    },
  },
}];

const resultat = $json;
const image = (resultat.images && resultat.images[0]) || resultat.image || null;
return [{
  json: {
    imageExploitable: Boolean(image && image.url),
    imageUrl: image ? image.url : null,
  },
}];

return [{
  json: {
    erreur: {
      code: 'generation_echouee',
      message: "La génération n'a pas produit d'image exploitable. Réessaie ; si le problème persiste, vérifie la configuration fal.ai côté n8n.",
    },
  },
}];

const contexte = $('Construire le prompt').item.json;
const image = $('Évaluer le résultat').item.json;
return [{
  json: {
    reference: contexte.reference,
    statut: 'en_cours',
    cycle_type: 'generation',
    image_url: image.imageUrl,
    prompt: contexte.promptComplet,
    payload: contexte.payloadFal,
  },
}];

const ligne = $json;
return [{
  json: {
    cycle_id: ligne.id,
    reference: ligne.reference,
    image_url: ligne.image_url,
    prompt: ligne.prompt,
  },
}];
